BOIL={'Scroll al inicio','Contacto inmediato','Hola! Por este medio te responderemos de inmediato','Whatsapp','Quiero recibir consejos','×','Ir al contenido','Hola! Te responderemos inmediatamente por este medio'}
def grp(p):
    s,t=p['slug'],p['title']
    if 'Página no encontrada' in t: return 'descartada_404'
    if s.startswith('2025__') and s.count('__')==3: return 'blog_articulo'
    if s.startswith(('category','author','2025__')) or s in('blog','blog-legacy','borrador'): return 'blog_listado'
    if s in('login','user','register','password-reset','members','tienda','mis-reportes','preview-mis-reportes','panel-tecnico'): return 'cuenta_sistema'
    if s=='sample-page': return 'descartada_plantilla'
    if 'Rediseno (borrador)' in t or s in('home','checklist-precompra','top-5-problemas','puntos-importantes','preview-home','preview-legales'): return 'actual_rediseno_2026'
    if s in('nosotros','contacto','contact','centro-de-ayuda','informe-ejemplo','guia-2','precios','servicios','servicios-1'): return 'actual_publica'
    if s in('terminos-y-condiciones','libro-de-reclamaciones'): return 'legal'
    if any(k in s for k in('boost','landing','campana','unico','verbal-gratis','gracias','asesora','asesoria-pre','venta-sin','gratis')): return 'landing_campana'
    return 'legacy'
