for g in order:
    gp=[p for p in pages if p['grupo']==g]
    if not gp: continue
    L+=[f"## {names[g]} ({len(gp)})",""]
    for p in gp:
        L+=[f"### {p['url']}",f"- title: {p['seo']['title']} | robots: {p['seo']['robots']}",f"- meta description: {p['seo']['meta_description']}",""]
        if g in('descartada_404','cuenta_sistema','descartada_plantilla'): continue
        L+=p['texto']+[""]
open('contenido.md','w').write("\n".join(L))
